package com.presaince.glasstube.feature.player

import com.presaince.glasstube.data.model.CaptionTrackInfo
import com.presaince.glasstube.data.model.Cue

/**
 * The words on screen at [positionMs], or null between cues.
 *
 * Cues are in start order but need not be tidy: an auto-generated track can carry two cues over
 * the same seconds. Every cue running at the moment is joined with a line break, which is what
 * the viewer would have read had the captions been drawn as a block. A cue's end is exclusive,
 * so a cue that ends at 12.0 is gone at 12.0 rather than lingering for a tick.
 *
 * Pure, and it runs four times a second on the player's tick, so the lookup is a binary search
 * with a short walk back for overlaps rather than a scan of the whole track.
 */
fun cueAt(cues: List<Cue>, positionMs: Long): String? {
    if (cues.isEmpty()) return null
    val seconds = positionMs.coerceAtLeast(0L) / 1000.0

    var low = 0
    var high = cues.lastIndex
    var last = -1
    while (low <= high) {
        val mid = (low + high) ushr 1
        if (cues[mid].startSec <= seconds) {
            last = mid
            low = mid + 1
        } else {
            high = mid - 1
        }
    }
    if (last < 0) return null

    val lines = ArrayDeque<String>()
    // A cue that started long ago and still runs is rare but possible, so the walk back stops at
    // a handful rather than trusting the whole track.
    var index = last
    var steps = 0
    while (index >= 0 && steps < OVERLAP_WALK) {
        val cue = cues[index]
        if (cue.startSec <= seconds && cue.endSec > seconds) {
            val text = cue.text.trim()
            if (text.isNotEmpty()) lines.addFirst(text)
        }
        index--
        steps++
    }
    return lines.joinToString("\n").ifEmpty { null }
}

/** How far back an overlap is looked for. Auto-generated tracks carry at most two-line cues. */
private const val OVERLAP_WALK = 4

/**
 * Which track to turn on: the reader's stored language when the video still offers it, otherwise
 * a human track before a machine one and English before the rest. Null means no captions at all,
 * and the CC control says so instead of offering a menu that would play nothing.
 */
fun pickCaptionTrack(tracks: List<CaptionTrackInfo>, stored: String?): CaptionTrackInfo? {
    if (tracks.isEmpty()) return null
    stored?.takeIf { it.isNotBlank() }?.let { wanted ->
        tracks.firstOrNull { it.languageTag.equals(wanted, ignoreCase = true) }?.let { return it }
    }
    return tracks.firstOrNull { !it.autoGenerated && it.languageTag.startsWith("en") }
        ?: tracks.firstOrNull { !it.autoGenerated }
        ?: tracks.firstOrNull { it.languageTag.startsWith("en") }
        ?: tracks.first()
}

/**
 * What a tap on the CC menu means, as the two things that have to change together: the language to
 * store and whether captions are on.
 *
 * The menu has no "on" row of its own — Off, then one row per track — so a track tap is the ask.
 * That rule lived in a callback and was missed: the track was stored, the cues were fetched, and
 * captions stayed off, so the tap changed nothing anyone could see (`captions tap`). One function
 * with one test is the whole guard.
 */
data class CaptionPick(val languageTag: String?, val on: Boolean)

fun captionPick(track: CaptionTrackInfo?): CaptionPick =
    CaptionPick(languageTag = track?.languageTag, on = track != null)

/** Caption text sizes, smallest first. Stored as an index so a backup survives a reorder. */
enum class CaptionSize(val label: String, val sp: Float) {
    SMALL("Small", 14f),
    MEDIUM("Medium", 17f),
    LARGE("Large", 21f);

    companion object {
        fun of(index: Int): CaptionSize = entries.getOrElse(index) { MEDIUM }
    }
}

/**
 * What the CC control draws and what a pick means. Null on the pick is "off", which is the same
 * choice as the first item in the menu, so the control has one callback rather than two.
 */
data class CaptionChoice(
    val tracks: List<CaptionTrackInfo> = emptyList(),
    val on: Boolean = false,
    val chosen: CaptionTrackInfo? = null,
    /** True once the list has been asked for, so the control does not appear and then vanish. */
    val loaded: Boolean = false,
)
